/* vm_compiler.h — the compiler inside the VM, for one instruction (Sprint 077; BLACKBOARD Decision 2026-10-14,
 * copy-and-patch at the encoder level, the stencil key). Its bytes and address in; the arm64 words
 * src/w2m/vm_backend.py's compile_insn gives out, built from the stencil table (stencil_table.h, generated by
 * scripts/gen_stencil_table.py), the decoder (x86_decode.c) and the encoders (a64_encoder.c).
 * tests/test_vm_compiler_c.py holds the C equal to the Python.
 */
#ifndef W2M_VM_COMPILER_H
#define W2M_VM_COMPILER_H

#include "x86_decode.h"

/* vmc_compile's failures: the instruction is compiled by the host */
enum vmc_status {
    VMC_DECODE = -1,        /* the bytes do not decode, or their operands do not */
    VMC_NO_STENCIL = -2,    /* no key in the table */
    VMC_NO_CHOICE = -3,     /* a refined key with no stencil for this value's feature */
    VMC_ENCODER = -4,       /* an encoder refused its arguments */
    VMC_FULL = -5,          /* more words than the output holds */
    VMC_KEY_SIZE = -6,      /* more operands, registers or values than the key holds */
};

/* compile_insn's flag arguments: nzcv_from as an index of [none, vm_backend.NZCV_CONDITIONS...] */
struct vmc_flags {
    int nzcv_from;
    int live_after;
    int nzcv_out;
};

#define VMC_MAX_KEY 160
#define VMC_MAX_VALUES 24

/* The key's bytes (as scripts/gen_stencil_table.py key_bytes writes them) and the decoded values
 * (stencil_census.decoded_form) of the instruction at code[0..n), at `address`: the key's length, or a vmc_status.
 * `length` gets the instruction's length. */
int vmc_key(const u8 *code, int n, u64 address, const struct vmc_flags *flags, u8 *key, u64 *values,
            int *nvalues, int *length);

/* The words of the instruction at code[0..n), at `address`, placed at `base`, a taken branch going to `exit_va`;
 * `symbols` are the runtime's addresses of the table's symbols (vmc_symbol_name). Returns the word count, or a
 * vmc_status. */
int vmc_compile(const u8 *code, int n, u64 address, u64 base, u64 exit_va, const struct vmc_flags *flags,
                const u64 *symbols, u32 *out, int max_words);

#endif
